<!DOCTYPE html>
<html lang="ko">
<head>
<meta charset="UTF-8">
<title>롯데월드타워 설계 과정 인터랙티브</title>
<style>
  body{margin:0;font-family:Arial,Helvetica,sans-serif;background:#111;color:#eee;}
  #container{display:flex;flex-direction:column;height:100vh;}
  #header{padding:10px;background:#222;display:flex;align-items:center;justify-content:space-between;}
  #header h1{margin:0;font-size:1.2rem;}
  #header span{font-size:0.9rem;color:#bbb;}
  #main{flex:1;display:flex;overflow:hidden;}
  #sidebar{width:300px;background:#222;overflow-y:auto;padding:10px;}
  #sidebar h2{font-size:1rem;margin-top:1rem;}
  #sidebar button{width:100%;margin:5px 0;padding:8px;background:#444;color:#eee;border:none;cursor:pointer;}
  #sidebar button.active{background:#666;}
  #sidebar img{width:100%;margin-top:5px;}
  #viewer{flex:1;background:#000;}
  .diagram{margin-top:10px;}
  .diagram img{width:100%;}
  .note{font-size:0.8rem;color:#bbb;margin-top:5px;}
  @media (max-width:600px){
    #sidebar{width:100%;height:200px;overflow-y:auto;}
    #main{flex-direction:column;}
    #viewer{height:calc(100vh - 200px);}
  }
</style>
</head>
<body>
<div id="container">
  <div id="header">
    <h1>롯데월드타워 설계 과정</h1>
    <span>모델: gpt-oss-20b</span>
  </div>
  <div id="main">
    <div id="sidebar">
      <h2>설계 단계</h2>
      <button data-stage="0" class="active">기본 배치도</button>
      <button data-stage="1">기준층 평면도</button>
      <button data-stage="2">입면도</button>
      <button data-stage="3">단면도</button>
      <button data-stage="4">완성 모델</button>
      <div id="diagrams"></div>
    </div>
    <div id="viewer"></div>
  </div>
</div>

<script src="../runtime/three-runtime.js"></script>
<script>
const stages = [
  {name:"배치도", img:"data:image/svg+xml;base64,PHN2ZyB3aWR0aD0iMzAwIiBoZWlnaHQ9IjEwMCI+PHJlY3Qgd2lkdGg9IjMwMCIgaGVpZ2h0PSIxMDAiIGZpbGw9IiM0NDQiLz48dGV4dCB4PSI1MCIgeT0iNTAlIiBmb250LXNpemU9IjE0IiBmaWxsPSIjZmZmIj5CYW5kYXRpYw=="} ,
  {name:"기준층 평면도", img:"data:image/svg+xml;base64,PHN2ZyB3aWR0aD0iMzAwIiBoZWlnaHQ9IjEwMCI+PHJlY3Qgd2lkdGg9IjMwMCIgaGVpZ2h0PSIxMDAiIGZpbGw9IiM0NDQiLz48dGV4dCB4PSI1MCIgeT0iNTAlIiBmb250LXNpemU9IjE0IiBmaWxsPSIjZmZmIj5QZXJtaW5kZXI= "} ,
  {name:"입면도", img:"data:image/svg+xml;base64,PHN2ZyB3aWR0aD0iMzAwIiBoZWlnaHQ9IjEwMCI+PHJlY3Qgd2lkdGg9IjMwMCIgaGVpZ2h0PSIxMDAiIGZpbGw9IiM0NDQiLz48dGV4dCB4PSI1MCIgeT0iNTAlIiBmb250LXNpemU9IjE0IiBmaWxsPSIjZmZmIj5JcG1lbmRv= "} ,
  {name:"단면도", img:"data:image/svg+xml;base64,PHN2ZyB3aWR0aD0iMzAwIiBoZWlnaHQ9IjEwMCI+PHJlY3Qgd2lkdGg9IjMwMCIgaGVpZ2h0PSIxMDAiIGZpbGw9IiM0NDQiLz48dGV4dCB4PSI1MCIgeT0iNTAlIiBmb250LXNpemU9IjE0IiBmaWxsPSIjZmZmIj5Eb2xpbmRv= "} ,
  {name:"완성 모델", img:"data:image/svg+xml;base64,PHN2ZyB3aWR0aD0iMzAwIiBoZWlnaHQ9IjEwMCI+PHJlY3Qgd2lkdGg9IjMwMCIgaGVpZ2h0PSIxMDAiIGZpbGw9IiM0NDQiLz48dGV4dCB4PSI1MCIgeT0iNTAlIiBmb250LXNpemU9IjE0IiBmaWxsPSIjZmZmIj5XYW5jZW4= "} 
];

const viewer = document.getElementById('viewer');
const diagrams = document.getElementById('diagrams');
const buttons = document.querySelectorAll('#sidebar button');

let scene, camera, renderer, controls, tower;
initThree();
loadStage(0);

buttons.forEach(btn=>{
  btn.addEventListener('click',()=>{ 
    buttons.forEach(b=>b.classList.remove('active'));
    btn.classList.add('active');
    const idx=+btn.dataset.stage;
    loadStage(idx);
  });
});

function initThree(){
  scene=new THREE.Scene();
  camera=new THREE.PerspectiveCamera(45,viewer.clientWidth/viewer.clientHeight,0.1,2000);
  camera.position.set(0,200,400);
  renderer=new THREE.WebGLRenderer({antialias:true});
  renderer.setSize(viewer.clientWidth,viewer.clientHeight);
  viewer.appendChild(renderer.domElement);
  controls=new THREE.OrbitControls(camera,renderer.domElement);
  controls.enableDamping=true;
  const light=new THREE.DirectionalLight(0xffffff,1);
  light.position.set(1,1,1);
  scene.add(light);
  const ambient=new THREE.AmbientLight(0x404040);
  scene.add(ambient);
  animate();
}

function animate(){requestAnimationFrame(animate);controls.update();renderer.render(scene,camera);}

function clearTower(){if(tower){scene.remove(tower);tower=null;}}
function loadStage(idx){
  clearTower();
  const stage=stages[idx];
  diagrams.innerHTML=`<div class="diagram"><img src="${stage.img}" alt="${stage.name}"><div class="note">${stage.name} (단위: m, 추정치)</div></div>`;
  if(idx===4){ // 완성 모델
    tower=createTower();
    scene.add(tower);
  }
}

function createTower(){
  const group=new THREE.Group();
  const baseHeight=555;
  const levels=123;
  const baseSize=200;
  const step=baseHeight/levels;
  for(let i=0;i<levels;i++){
    const size=baseSize*(1-0.005*i);
    const geom=new THREE.BoxGeometry(size,size,step);
    const mat=new THREE.MeshLambertMaterial({color:0x888888});
    const block=new THREE.Mesh(geom,mat);
    block.position.y=step/2+i*step;
    group.add(block);
  }
  return group;
}
</script>
</body>
</html>
